async function init(){
 const sessionEpoch=state.sessionEpoch;let stamp=null;
 try{
  const result=await api('/auth/me');
  if(authRequestPending||sessionEpoch!==state.sessionEpoch)return;
  state.user=result.user;state.sessionEpoch++;resetAccount();stamp=contextStamp();
  if(['groups','report'].includes(location.hash.slice(1)))await loadManagement();stamp=contextStamp();
  const requested=validDate(new URLSearchParams(location.search).get('date'));state.date=requested||today();
  state.view=['day','achievements','account','groups',...(state.selectedGroup&&state.canViewRecords?['report']:[])].includes(location.hash.slice(1))?location.hash.slice(1):'day';
  await loadDay();if(!sameContext(stamp))return;
  if(state.view==='achievements')await loadAchievements();
  if(state.view==='account')await loadCities();if(state.view==='groups')await loadManagement();if(state.view==='report'){state.selectedChild=null;clearData();state.reportDate=validDate(new URLSearchParams(location.search).get('date'))||shiftDate(reportToday(),-1);if(state.reportDate>reportToday())state.reportDate=reportToday();state.reportOffset=0;await loadDailyReport();}
 }catch(error){
  if(!authRequestPending&&(stamp?sameContext(stamp):sessionEpoch===state.sessionEpoch)&&error.status!==401)state.error='تعذّر فتح الدفتر. تأكّد أن الخادم يعمل، ثم أعد المحاولة';
 }finally{state.loading=false;render();}
 if(state.user&&state.inviteToken&&!authRequestPending)await previewInvite();
}
let lastEligibility='';let lastScheduleRetry=0;let lastAchievementRefresh=0;let scheduleRefreshBusy=false;
async function scheduleTick(){if(state.view==='report'||!state.user||!state.day)return;const cityToday=today();if(state.day.schedule?.today&&state.day.schedule.today!==cityToday){if(state.date===state.day.schedule.today){await changeDate(cityToday);return;}try{await loadDay(state.date);if(state.view==='day')render();}catch{}return;}const signature=JSON.stringify(scheduleKeys());const eligibilityChanged=signature!==lastEligibility;if(eligibilityChanged){lastEligibility=signature;if(state.view==='day')render();}if(state.view==='achievements'&&!scheduleRefreshBusy&&(eligibilityChanged||Date.now()-lastAchievementRefresh>=60000)){scheduleRefreshBusy=true;try{await loadAchievements();render();}catch(error){handleError(error);}finally{scheduleRefreshBusy=false;}}if(scheduleUnavailable()&&Date.now()-lastScheduleRetry>300000){lastScheduleRetry=Date.now();try{await loadDay();if(state.view==='day')render();}catch{}}}
const scheduleTimer=typeof window.setInterval==='function'?window.setInterval(()=>scheduleTick().catch(()=>{}),30000):null;scheduleTimer?.unref?.();
init();

root.addEventListener('keydown',event=>{if(!state.groupCreating)return;if(event.key==='Escape'&&!state.busy){state.groupCreating=false;state.groupDeleting=false;render();root.querySelector('[data-action="new-group"]')?.focus();}if(event.key==='Tab'){const controls=[...root.querySelectorAll('.group-create-dialog input,.group-create-dialog button')].filter(el=>!el.disabled);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
